class Lfu(int capacity)
{
    readonly Dictionary<string, (int Freq, int LastUsed)> items = new();
    int clock;
    public void Get(string k)
    {
        if (items.TryGetValue(k, out var e)) items[k] = (e.Freq + 1, ++clock);
    }
    public void Put(string k)
    {
        if (!items.ContainsKey(k) && items.Count == capacity)
        {
            var victim = items.OrderBy(p => p.Value.Freq).ThenBy(p => p.Value.LastUsed).First().Key;
            Console.WriteLine($"evict {victim}");
            items.Remove(victim);
        }
        items[k] = items.TryGetValue(k, out var e) ? (e.Freq + 1, ++clock) : (1, ++clock);
    }
    public IEnumerable<string> Keys() => items.Keys.OrderBy(k => k);
}

