class Breaker(int threshold, int openMs)
{
    string state = "Closed";
    int failures, openedAt;

    public string Call(int now, bool ok)
    {
        if (state == "Open")
        {
            if (now - openedAt < openMs) return "rejected";
            state = "HalfOpen";
        }
        if (ok) { failures = 0; state = "Closed"; }
        else if (state == "HalfOpen" || ++failures >= threshold) { state = "Open"; openedAt = now; }
        return $"{(ok ? "ok" : "fail")} -> {state}";
    }
}

