		}
		if len(live) < limit[r.dep] {
			live = append(live, r.t+r.dur)
			out = append(out, r.dep+":ok")
		} else {
			out = append(out, r.dep+":rejected")
		}
		busy[r.dep] = live
	}
	fmt.Println(strings.Join(out, " "))
}

