package main

import "fmt"

func assign(partitions, consumers int) [][]int {
	out := make([][]int, consumers)
	per, extra := partitions/consumers, partitions%consumers
	p := 0
	for c := range out {
		n := per
		if c < extra {
			n++
		}
		out[c] = []int{}
		for i := 0; i < n; i++ {
			out[c] = append(out[c], p)
			p++
		}
	}
	return out
}

func main() {
	fmt.Println(assign(7, 3))
	fmt.Println(assign(3, 4))
}
